package Streams;import java.util.*;import java.util.stream.Collectors;public class Data {    static void main(String[] args) {        ArrayList<Integer> arr=new ArrayList<>();        ArrayList<String> arr1=new ArrayList<>();        arr1.add("Aman");        arr1.add("Pradeep");        arr1.add("Ujwal");        arr1.add("Raju");        arr.add(20);        arr.add(30);        arr.add(15);        List<Integer> list =arr.stream()                .filter(e->e%2==0)                .collect(Collectors.toList());        System.out.println(list);        arr1.stream()                .filter(e->e.startsWith("R") && e.endsWith("u"))                .forEach(System.out::println);    }}